# LIGHTNESS PREMIUM — SINGLE FILE EDITION
# Full bot source + supplied owner QR embedded; no project folders required.
import sys, types, base64, os
BOT_OWNER_ID = 1433457392917676138
_OWNER_QR_B64 = ''
_EMBEDDED_MODULES = {
    'core.permissions': '',
    'core.embeds': '',
    'core.emoji': '',
    'core.__init__': '',
    'core.ui': '',
    'core.store': '',
    'cogs.permissions': '',
    'cogs.automod': '',
    'cogs.roles': '',
    'cogs.__init__': '',
    'cogs.serverinfo': '',
    'cogs.goodbye': '',
    'cogs.welcome': '',
    'cogs.help': '',
    'cogs.tickets': '',
    'cogs.announcements': '',
    'cogs.moderation': '',
    'cogs.dashboard': '',
    'cogs.giveaways': '',
    'cogs.settings': '',
}

def _load_embedded_modules():
    for name in _EMBEDDED_MODULES:
        if name not in sys.modules:
            mod = types.ModuleType(name)
            mod.__file__ = '<embedded:%s>' % name
            mod.__package__ = name.rpartition('.')[0] if '.' in name else name
            sys.modules[name] = mod
    for name, encoded in _EMBEDDED_MODULES.items():
        if name.endswith('.__init__'): continue
        mod = sys.modules[name]
        exec(compile(base64.b64decode(encoded).decode('utf-8'), mod.__file__, 'exec'), mod.__dict__)
_load_embedded_modules()
try:
    _qr_path = os.path.join(os.path.dirname(__file__) or '.', '.owner_qr_embedded.png')
    if not os.path.exists(_qr_path):
        with open(_qr_path, 'wb') as _f: _f.write(base64.b64decode(_OWNER_QR_B64))
    os.environ.setdefault('LIGHTNESS_OWNER_QR', _qr_path)
except Exception:
    pass

import os
import discord
from discord.ext import commands
from dotenv import load_dotenv
from core.store import Store
from core.emoji import EmojiManager
from core.permissions import PermissionManager
from cogs.dashboard import DashboardCog
from cogs.welcome import WelcomeCog
from cogs.goodbye import GoodbyeCog
from cogs.tickets import TicketCog
from cogs.giveaways import GiveawayCog
from cogs.announcements import AnnouncementCog
from cogs.serverinfo import ServerInfoCog
from cogs.permissions import PermissionsCog
from cogs.help import HelpCog
from cogs.moderation import ModerationCog
from cogs.automod import AutoModCog
from cogs.roles import RolesCog
from cogs.settings import SettingsCog

load_dotenv()
TOKEN=os.getenv('DISCORD_TOKEN')
if not TOKEN:
    raise RuntimeError('DISCORD_TOKEN is missing. Add it in Railway Variables.')

OWNER_ID=int(os.getenv('BOT_OWNER_ID','1433457392917676138'))
TEST_GUILD_ID=int(os.getenv('TEST_GUILD_ID','0') or 0)

intents=discord.Intents.default()
intents.guilds=True
intents.members=True
intents.message_content=True
intents.presences=True

class Lightness(commands.Bot):
    def __init__(self):
        super().__init__(command_prefix='!', intents=intents)
        self.owner_id=OWNER_ID
        self.store=Store('data/guilds')
        self.emoji_manager=EmojiManager()
        self.perms=PermissionManager(self.store, OWNER_ID)

    async def setup_hook(self):
        await self.add_cog(DashboardCog(self))
        await self.add_cog(WelcomeCog(self))
        await self.add_cog(GoodbyeCog(self))
        await self.add_cog(TicketCog(self))
        await self.add_cog(GiveawayCog(self))
        await self.add_cog(AnnouncementCog(self))
        await self.add_cog(ServerInfoCog(self))
        await self.add_cog(PermissionsCog(self))
        await self.add_cog(HelpCog(self))
        await self.add_cog(ModerationCog(self))
        await self.add_cog(AutoModCog(self))
        await self.add_cog(RolesCog(self))
        await self.add_cog(SettingsCog(self))
        if TEST_GUILD_ID:
            guild=discord.Object(id=TEST_GUILD_ID)
            self.tree.copy_global_to(guild=guild)
            await self.tree.sync(guild=guild)
        else:
            await self.tree.sync()

bot=Lightness()

@bot.event
async def on_ready():
    for g in bot.guilds:
        cfg=bot.store.load(g.id).get('emoji_map',{})
        g._state._lightness_emoji_config=cfg
        bot.emoji_manager.refresh(g,cfg)
    print(f'LIGHTNESS PREMIUM online as {bot.user} | guilds={len(bot.guilds)}')

@bot.event
async def on_guild_join(guild):
    cfg=bot.store.load(guild.id).get('emoji_map',{})
    guild._state._lightness_emoji_config=cfg
    bot.emoji_manager.refresh(guild,cfg)

@bot.event
async def on_guild_remove(guild):
    bot.emoji_manager.clear(guild.id)

bot.run(TOKEN)
